def main() -> None:
    path = Path("localization/ru_rescue_with_signs.tsv")
    rows = list(csv.reader(path.open("r", encoding="utf-8", newline=""), delimiter="\t"))
    changed = 0
    for row in rows:
        if len(row) >= 8 and "QuestSystem/DT_Quests" in row[2] and row[0] in QUEST_TRANSLATIONS:
            if row[7] != QUEST_TRANSLATIONS[row[0]]:
                row[7] = QUEST_TRANSLATIONS[row[0]]
                changed += 1
    with path.open("w", encoding="utf-8", newline="") as f:
        csv.writer(f, delimiter="\t", lineterminator="\n").writerows(rows)
    print(f"changed {changed}")


if __name__ == "__main__":
    main()
